// Eager loading - loads related data in single query
var products = await _context.Products
    .Include(p => p.Category)
    .Include(p => p.Images)
    .ThenInclude(i => i.UploadedBy)
    .Where(p => p.Price > 100)
    .OrderByDescending(p => p.CreatedAt)
    .ToListAsync();

// Filtered Include (EF Core 5+)
var productsWithImages = await _context.Products
    .Include(p => p.Images.Where(i => i.IsPrimary))
    .ToListAsync();

// Explicit loading
var product = await _context.Products.FirstAsync(p => p.Id == 1);
await _context.Entry(product).Collection(p => p.Images).LoadAsync();

// Split query to avoid Cartesian explosion
var products = await _context.Products
    .Include(p => p.Images)
    .AsSplitQuery()
    .ToListAsync();

// Projection - most efficient
var products = await _context.Products
    .Where(p => p.IsActive)
    .Select(p => new ProductDto
    {
        Id = p.Id,
        Name = p.Name,
        Price = p.Price,
        CategoryName = p.Category.Name,
        ImageUrl = p.Images.FirstOrDefault(i => i.IsPrimary)!.Url
    })
    .ToListAsync();

// Benefits:
// - Single optimized SQL query
// - No entity tracking (faster)
// - Only selected columns returned
// - Avoids over-fetching

// For complex projections, use AutoMapper
var products = await _context.Products
    .ProjectTo<ProductDto>(_mapper.ConfigurationProvider)
    .ToListAsync();
